"""Test maps generated by map CLASS, to judge a bot per class on transferable map features rather than on the few known
contest maps.

abyss_tools.maps.mapgen keeps every open tile connected and starts at most 12 segments per team, so it never makes
separated or gated far maps and never a large opening army. This generator makes six families:

  SEP        two halves with no path between them (kelp across the map and across the wrap), each team confined to
             its half; beds on both halves; fountain boxes entered only through a portal (as on Portals).
  FAR_gated  a spawn room walled off from a kelp maze; the room reaches the maze only through portals, so every
             fountain (all in the maze) needs a portal; head-to-head BFS >= 40 (Trauma / Stronghold-like).
  RICH       large, many beds and fountains, 5-8 dragons per team with a starting total length of 40-60 (often one
             long coiled dragon, Slithery-like); the unit cap binds early.
  SMALL      <= 1100 tiles, early contact (head BFS <= 30).
  LARGE      > 1100 tiles, open (little kelp), sparse beds, head BFS < 40.
  SCATTER    no fountains (every bed has maxGap > 10), beds spread evenly on a jittered grid (SMALL or LARGE size).

Each map is checked against the class rules (feat() / cls2() below: contact distance, pearl rate near the spawn, starting
length, area, whether the fountains need a portal) and regenerated with the next derived seed until it lands in its class;
the manifest records how many attempts each map took. Everything is exactly symmetric under the declared SYMMETRY
(x: y -> h-1-y, y: x -> w-1-x, xy: 180-degree rotation; the engine checks beds, we also keep kelp, portals and
dragons symmetric), portal pairs have two ends of one orientation, dragons are straight or coiled bodies inside the
map (no wrap between segments, no kelp or portal between consecutive segments) with a free first step.

  python -m abyss_tools.maps.mapgen_cls --out maps/cls                       # 24 maps per class
  python -m abyss_tools.maps.mapgen_cls --out maps/cls --classes SEP,RICH --count 30 --seed 7
  python -m abyss_tools.maps.mapgen_cls --check maps/cls            # engine parse + symmetry + class confusion
  python -m abyss_tools.maps.mapgen_cls --check maps/cls --play 2   # + starter vs starter games, 2 maps a class
  python -m abyss_tools.maps.mapgen_cls --show maps/cls/SEP/SEP_00.map
  abyss-mapgen-cls ...

Output: <out>/<CLASS>/<CLASS>_<nn>.map and <out>/manifest.json (seed, attempts, features, tags).
Pure stdlib; --check loads every map in the engine through the installed unswbc's own Python, --play needs `unswbc` and a
starter bot folder (--bots).
"""
import argparse
import collections
import concurrent.futures as cf
import hashlib
import json
import os
import random
import shutil
import subprocess
import sys

from ..paths import bots_dir, unswbc

INF = 10 ** 9
DIRS = "NESW"
DXY = {"N": (0, -1), "E": (1, 0), "S": (0, 1), "W": (-1, 0)}
DELTA_DIR = {v: k for k, v in DXY.items()}
CLASSES = ["SEP", "FAR_gated", "RICH", "SMALL", "LARGE", "SCATTER"]


class Retry(Exception):
    """This attempt cannot be completed; the caller retries with the next derived seed."""


# ---------------------------------------------------------------------------------------------------------------
# Map model (engine semantics as in abyss_tools.replay.state.Board)
# Edges: ("H", x, y) = top side of tile (x, y); ("V", x, y) = left side of tile (x, y); coordinates wrap.
# ---------------------------------------------------------------------------------------------------------------
class M:
    def __init__(self, w, h, sym, rng=None):
        self.w, self.h, self.sym, self.r = w, h, sym, rng
        self.kelp = set()
        self.portal = {}      # edge -> pair id
        self.partner = {}     # edge -> edge
        self.beds = {}        # tile -> (minGap, maxGap)
        self.dragons = []     # (team 0/1, [tiles, head first]); A and its mirror B are appended together
        self.npairs = 0
        self.name = ""

    # ---- symmetry (engine: x flips y, y flips x, xy rotates by 180 degrees) ----
    def T(self, t):
        x, y = t
        if self.sym in ("y", "xy"):
            x = self.w - 1 - x
        if self.sym in ("x", "xy"):
            y = self.h - 1 - y
        return (x, y)

    def TE(self, e):
        k, x, y = e
        if self.sym in ("y", "xy"):
            x = self.w - 1 - x if k == "H" else (self.w - x) % self.w
        if self.sym in ("x", "xy"):
            y = (self.h - y) % self.h if k == "H" else self.h - 1 - y
        return (k, x, y)

    # ---- geometry ----
    def tiles(self):
        return [(x, y) for y in range(self.h) for x in range(self.w)]

    def side(self, t, d):
        x, y = t
        if d == "N":
            return ("H", x, y)
        if d == "S":
            return ("H", x, (y + 1) % self.h)
        if d == "W":
            return ("V", x, y)
        return ("V", (x + 1) % self.w, y)

    def edge_tiles(self, e):
        k, x, y = e
        if k == "H":
            return (x, (y - 1) % self.h), (x, y)
        return ((x - 1) % self.w, y), (x, y)

    def adj(self, t, d):
        return ((t[0] + DXY[d][0]) % self.w, (t[1] + DXY[d][1]) % self.h)

    def plain(self, t, d):
        e = self.side(t, d)
        if e in self.kelp or e in self.portal:
            return None
        return self.adj(t, d)

    def step(self, t, d):
        e = self.side(t, d)
        if e in self.kelp:
            return None
        if e in self.portal:
            k, px, py = self.partner[e]
            if k == "H":
                return (px % self.w, (py if d == "S" else py - 1) % self.h)
            return ((px if d == "E" else px - 1) % self.w, py % self.h)
        return self.adj(t, d)

    def bfs(self, srcs, portals=True, within=None):
        nbf = self.step if portals else self.plain
        dist = {s: 0 for s in srcs}
        q = list(srcs)
        i = 0
        while i < len(q):
            t = q[i]
            i += 1
            dt = dist[t] + 1
            for d in DIRS:
                n = nbf(t, d)
                if n is not None and n not in dist and (within is None or n in within):
                    dist[n] = dt
                    q.append(n)
        return dist

    # ---- symmetric edits ----
    def add_kelp(self, e):
        for u in (e, self.TE(e)):
            if u not in self.portal:
                self.kelp.add(u)

    def del_kelp(self, e):
        self.kelp.discard(e)
        self.kelp.discard(self.TE(e))

    def can_portal(self, a, b):
        imgs = [a, b, self.TE(a), self.TE(b)]
        return a[0] == b[0] and len(set(imgs)) == 4 and not any(e in self.portal for e in imgs)

    def add_portal(self, a, b):
        assert self.can_portal(a, b)
        for u, v in ((a, b), (self.TE(a), self.TE(b))):
            self.kelp.discard(u)
            self.kelp.discard(v)
            self.portal[u] = self.portal[v] = self.npairs
            self.partner[u], self.partner[v] = v, u
            self.npairs += 1

    def del_portal(self, a):
        for u in (a, self.TE(a)):
            if u in self.portal:
                v = self.partner.pop(u)
                self.partner.pop(v, None)
                self.portal.pop(u)
                self.portal.pop(v, None)

    def set_bed(self, t, lo, hi):
        self.beds[t] = self.beds[self.T(t)] = (lo, hi)

    def del_bed(self, t):
        self.beds.pop(t, None)
        self.beds.pop(self.T(t), None)

    def add_dragon(self, body):
        self.dragons.append((0, list(body)))
        self.dragons.append((1, [self.T(t) for t in body]))

    def occupied(self):
        return {t for _, b in self.dragons for t in b}

    def heads(self, team=0):
        return [b[0] for tm, b in self.dragons if tm == team]

    def tdist(self, a, b):
        dx, dy = abs(a[0] - b[0]), abs(a[1] - b[1])
        return min(dx, self.w - dx) + min(dy, self.h - dy)

    def snapshot(self):
        return (set(self.kelp), dict(self.portal), dict(self.partner), self.npairs, dict(self.beds), list(self.dragons))

    def restore(self, s):
        self.kelp, self.portal, self.partner, self.npairs, self.beds, self.dragons = (
            set(s[0]), dict(s[1]), dict(s[2]), s[3], dict(s[4]), list(s[5]))

    # ---- file format (https://game.battlecode.au/docs/map-files) ----
    def edge_index(self, e):
        k, x, y = e
        return (2 * y) * (self.w + 1) + x if k == "H" else (2 * y + 1) * (self.w + 1) + x

    def text(self, name):
        out = [f"MAP {self.w} {self.h}", f"SYMMETRY {self.sym}", f"MAP_NAME {name}", f"TILE_COUNT {self.w * self.h}"]
        for y in range(self.h):
            for x in range(self.w):
                lo, hi = self.beds.get((x, y), (0, 0))
                out.append(f"TILE {x} {y} {lo} {hi}")
        rows = [(self.edge_index(e), 1, -1) for e in self.kelp]
        ids = {}
        for e in sorted(self.portal, key=self.edge_index):
            rows.append((self.edge_index(e), 2, ids.setdefault(self.portal[e], len(ids))))
        rows.sort()
        out.append(f"EDGE_COUNT {len(rows)}")
        out += [f"EDGE {i} {k} {p}" for i, k, p in rows]
        out.append(f"DRAGON_COUNT {len(self.dragons)}")
        for team, body in self.dragons:
            out.append(f"DRAGON {team} {len(body)} " + " ".join(f"{x} {y}" for x, y in body))
        out.append("END")
        return "\n".join(out) + "\n"

    def transposed(self):
        """Swap x and y (a vertical divide becomes horizontal): x <-> y symmetry, H <-> V edges."""
        t = M(self.h, self.w, {"x": "y", "y": "x", "xy": "xy"}[self.sym], self.r)
        sw = lambda e: ("V" if e[0] == "H" else "H", e[2], e[1])
        t.kelp = {sw(e) for e in self.kelp}
        t.portal = {sw(e): p for e, p in self.portal.items()}
        t.partner = {sw(e): sw(f) for e, f in self.partner.items()}
        t.npairs = self.npairs
        t.beds = {(y, x): v for (x, y), v in self.beds.items()}
        t.dragons = [(tm, [(y, x) for x, y in b]) for tm, b in self.dragons]
        return t


def edge_index_of(w, h, index):
    stride = w + 1
    col, row = index % stride, index // stride
    if index < 0 or row > 2 * h:
        return None
    if row % 2 == 0:
        if col == w or row == 2 * h:
            return None
        return ("H", col, row // 2)
    if col == w:
        return None
    return ("V", col, (row - 1) // 2)


def parse(text):
    m = None
    ends = collections.defaultdict(list)
    w = h = 0
    sym, name = "xy", ""
    for line in text.splitlines():
        p = line.split()
        if not p:
            continue
        if p[0] == "END":
            break
        if p[0] == "MAP":
            w, h = int(p[1]), int(p[2])
        elif p[0] == "SYMMETRY":
            sym = p[1]
        elif p[0] == "MAP_NAME":
            name = " ".join(p[1:])
        elif p[0] == "TILE_COUNT":
            m = M(w, h, sym)
            m.name = name
        elif p[0] == "TILE":
            x, y, lo, hi = map(int, p[1:5])
            if hi > 0:
                m.beds[(x, y)] = (lo, hi)
        elif p[0] == "EDGE":
            idx, kind, pid = map(int, p[1:4])
            e = edge_index_of(w, h, idx)
            if e is None or kind == 0:
                continue
            if kind == 1:
                m.kelp.add(e)
            else:
                m.portal[e] = pid
                ends[pid].append(e)
        elif p[0] == "DRAGON":
            team, n = int(p[1]), int(p[2])
            c = list(map(int, p[3:3 + 2 * n]))
            m.dragons.append((team, [(c[2 * i], c[2 * i + 1]) for i in range(n)]))
    for pid, lst in ends.items():
        if len(lst) == 2:
            m.partner[lst[0]], m.partner[lst[1]] = lst[1], lst[0]
    m.npairs = len(ends)
    return m


# ---------------------------------------------------------------------------------------------------------------
# Features and the class rules
# ---------------------------------------------------------------------------------------------------------------
def feat(m):
    W, H = m.w, m.h
    N = W * H
    A = [b for tm, b in m.dragons if tm == 0]
    B = [b for tm, b in m.dragons if tm == 1]
    dA = m.bfs([b[0] for b in A])
    dB = m.bfs([b[0] for b in B])
    dAp = m.bfs([b[0] for b in A], portals=False)
    contact = min((dA.get(b[0], INF) for b in B), default=INF)
    beds = m.beds
    rate = {t: 2.0 / (lo + hi) if lo + hi > 0 else 1.0 for t, (lo, hi) in beds.items()}
    R = sum(rate.values()) or 1e-9
    fount = [t for t, (lo, hi) in beds.items() if hi <= 10]
    own = [t for t in beds if dA.get(t, INF) < dB.get(t, INF)]
    tie = [t for t in beds if dA.get(t, INF) == dB.get(t, INF) < INF]
    Rown = sum(rate[t] for t in own) + 0.5 * sum(rate[t] for t in tie)
    need = lambda t: dAp.get(t, INF) > 1.5 * dA.get(t, INF) + 5
    Rown_need = sum(rate[t] for t in own if need(t)) / max(Rown, 1e-9)
    fd = min((dA.get(t, INF) for t in fount), default=None)
    fd_np = min((dAp.get(t, INF) for t in fount), default=None)
    Rf = sum(rate[t] for t in fount) / R
    loc = lambda r: sum(rate[t] for t in beds if dA.get(t, INF) <= r)
    lens = sorted([len(b) for b in A], reverse=True)
    deg = collections.Counter()
    for t in m.tiles():
        deg[t] = sum(1 for d in DIRS if m.step(t, d) is not None)
    f = dict(
        W=W, H=H, sym=m.sym, area=N, kelp_per_tile=round(len(m.kelp) / N, 3), portal_pairs=len(m.portal) // 2,
        corridor_share=round(sum(1 for t in deg if 0 < deg[t] <= 2) / N, 3), reach_share=round(len(dA) / N, 3),
        separated=contact >= INF, contact_bfs=None if contact >= INF else contact,
        beds=len(beds), pearl_rate=round(R, 2), rate_per_100=round(100 * R / N, 2),
        fount=len(fount), fount_rate_share=round(Rf, 2), fount_dist=None if fd is None or fd >= INF else fd,
        fount_dist_noportal=None if fd_np is None or fd_np >= INF else fd_np,
        fount_needs_portal=(fd is not None and fd < INF and (fd_np is None or fd_np > 1.5 * fd + 5)),
        own_supply_needs_portal=round(Rown_need, 2), rate_within10=round(loc(10), 2), rate_within20=round(loc(20), 2),
        start_dragons=len(A), start_len=sum(lens), start_max=lens[0] if lens else 0,
        bed_block_cover=block_cover(m))
    f["cls2"] = cls2(f)
    f["eco"] = "F" if f["fount_rate_share"] >= 0.5 else "S"
    f["gated"] = bool(f["fount_needs_portal"] or f["own_supply_needs_portal"] >= 0.5)
    return f


def cls2(f):
    if f["separated"]:
        return "SEP"
    if (f["contact_bfs"] or 0) >= 40:
        return "FAR"
    if f["rate_within20"] >= 20 or f["start_len"] >= 40:
        return "RICH"
    if f["area"] <= 1100:
        return "SMALL"
    return "LARGE"


def block_cover(m, s=8):
    """Share of s x s blocks holding at least one bed (how spread the beds are)."""
    blocks = {(x // s, y // s) for x, y in m.tiles()}
    hit = {(x // s, y // s) for x, y in m.beds}
    return round(len(hit) / len(blocks), 2)


# What each family must satisfy (the classifier's verdict plus the family's own defining features).
INTENT = {
    "SEP": lambda f: f["cls2"] == "SEP" and f["reach_share"] >= 0.49,
    "FAR_gated": lambda f: f["cls2"] == "FAR" and f["gated"] and f["reach_share"] >= 0.95,
    "RICH": lambda f: f["cls2"] == "RICH" and f["start_len"] >= 40 and 5 <= f["start_dragons"] <= 8,
    "SMALL": lambda f: f["cls2"] == "SMALL" and (f["contact_bfs"] or INF) <= 30,
    "LARGE": lambda f: f["cls2"] == "LARGE" and f["rate_per_100"] <= 1.5 and f["kelp_per_tile"] <= 0.15,
    "SCATTER": lambda f: f["cls2"] in ("SMALL", "LARGE") and f["fount"] == 0 and f["beds"] > 0
    and f["bed_block_cover"] >= 0.6,
}
# The classifier alone (for the confusion report): which cls2 / tags a family is meant to get.
EXPECT = {"SEP": ("SEP",), "FAR_gated": ("FAR",), "RICH": ("RICH",), "SMALL": ("SMALL",), "LARGE": ("LARGE",),
          "SCATTER": ("SMALL", "LARGE")}


def classifier_ok(fam, f):
    if f["cls2"] not in EXPECT[fam]:
        return False
    if fam == "FAR_gated":
        return f["gated"]
    if fam == "SCATTER":
        return f["fount"] == 0
    return True


# ---------------------------------------------------------------------------------------------------------------
# Building blocks
# ---------------------------------------------------------------------------------------------------------------
def connected(m, region, portals=True, seed=None):
    region = region if isinstance(region, (set, frozenset)) else set(region)
    s = seed if seed is not None else next(iter(sorted(region)))
    return len(m.bfs([s], portals=portals, within=region)) == len(region)


def rand_walls(m, density, region=None, maxlen=None, fails_max=60):
    """Straight symmetric kelp segments until ~density of all edges are kelp; a segment that would cut the region's
    tiles apart (plain edges) is undone."""
    r = m.r
    region = set(region) if region else set(m.tiles())
    rl = sorted(region)
    seed = rl[0]
    target = density * 2 * m.w * m.h
    maxlen = maxlen or max(3, min(m.w, m.h) // 3)
    fails = 0
    while len(m.kelp) < target and fails < fails_max:
        x, y = r.choice(rl)
        horiz = r.random() < 0.5
        n = r.randint(2, maxlen)
        es = [("H", (x + i) % m.w, y) if horiz else ("V", x, (y + i) % m.h) for i in range(n)]
        es = [e for e in es if all(t in region for t in m.edge_tiles(e))]
        added = {u for e in es for u in (e, m.TE(e)) if u not in m.kelp and u not in m.portal}
        if not added:
            fails += 1
            continue
        m.kelp |= added
        if not connected(m, region, portals=False, seed=seed):
            m.kelp -= added
            fails += 1
        else:
            fails = 0


def rand_portals(m, pairs, region=None):
    """Random same-orientation portal pairs on free edges (both images kept apart); undone if they cut the region."""
    r = m.r
    region = set(region) if region else set(m.tiles())
    placed = 0
    for _ in range(pairs * 40):
        if placed >= pairs:
            break
        k = r.choice("HV")
        a = (k, r.randrange(m.w), r.randrange(m.h))
        b = (k, r.randrange(m.w), r.randrange(m.h))
        imgs = [a, b, m.TE(a), m.TE(b)]
        if any(e in m.kelp or e in m.portal for e in imgs) or not m.can_portal(a, b):
            continue
        if not all(t in region for e in (a, b) for t in m.edge_tiles(e)):
            continue
        if min(m.tdist(m.edge_tiles(a)[1], m.edge_tiles(b)[1]), m.tdist(m.edge_tiles(a)[1], m.T(m.edge_tiles(b)[1]))) < 4:
            continue
        m.add_portal(a, b)
        if not connected(m, region):
            m.del_portal(a)
            continue
        placed += 1
    return placed


def body_straight(m, n):
    d = m.r.choice(DIRS)
    dx, dy = DXY[d]
    x, y = m.r.randrange(m.w), m.r.randrange(m.h)
    body = [(x - i * dx, y - i * dy) for i in range(n)]
    if any(not (0 <= a < m.w and 0 <= b < m.h) for a, b in body):
        return None
    return body


def body_coil(m, n):
    """A serpentine (boustrophedon) body in a small rectangle, head on an outer corner (Slithery's 25-long coil)."""
    r = m.r
    a = r.randint(3, 6)
    rows = -(-n // a)
    path = []
    for j in range(rows):
        xs = range(a) if j % 2 == 0 else range(a - 1, -1, -1)
        path += [(i, j) for i in xs]
    path = path[:n]
    if r.random() < 0.5:
        path = [(q, p) for p, q in path]
    fx, fy = r.random() < 0.5, r.random() < 0.5
    bw = max(p for p, _ in path) + 1
    bh = max(q for _, q in path) + 1
    if bw > m.w or bh > m.h:
        return None
    x0, y0 = r.randrange(m.w - bw + 1), r.randrange(m.h - bh + 1)
    return [(x0 + (bw - 1 - p if fx else p), y0 + (bh - 1 - q if fy else q)) for p, q in path]


def place_dragon(m, n, region=None, avoid=frozenset(), sep=4, gap=2, head_ok=None, tries=600):
    """One team-A dragon of length n (and its mirror for B). Straight up to 8, coiled beyond."""
    occ_a = {t for tm, b in m.dragons if tm == 0 for t in b}
    occ_b = {t for tm, b in m.dragons if tm == 1 for t in b}
    for _ in range(tries):
        body = body_straight(m, n) if n <= 8 else body_coil(m, n)
        if body is None:
            continue
        if region is not None and any(t not in region for t in body):
            continue
        if any(t in avoid for t in body):
            continue
        if head_ok is not None and not head_ok(body[0]):
            continue
        mirror = [m.T(t) for t in body]
        allb = set(body) | set(mirror)
        if len(allb) != 2 * n or any(t in occ_a or t in occ_b for t in allb):
            continue
        ok = True
        for i in range(n - 1):
            d = DELTA_DIR[(body[i + 1][0] - body[i][0], body[i + 1][1] - body[i][1])]
            if m.plain(body[i], d) != body[i + 1]:
                ok = False
                break
        if not ok:
            continue
        if not any((nb := m.step(body[0], d)) is not None and nb not in allb and nb not in occ_a and nb not in occ_b
                   for d in DIRS):
            continue
        if min(m.tdist(a, b) for a in body for b in (occ_b | set(mirror))) < sep:
            continue
        if occ_a and min(m.tdist(a, b) for a in body for b in occ_a) < gap:
            continue
        m.add_dragon(body)
        return body
    raise Retry(f"no room for a dragon of length {n}")


def fountain_cluster(m, center, k, region, gaps, occ):
    tiles = [t for t in m.bfs([center], portals=False, within=region) if t not in occ]
    tiles.sort(key=lambda t: m.tdist(t, center))
    for t in tiles[:k]:
        m.set_bed(t, *gaps)


def thin_rate(m, limit):
    """Drop random beds (with their mirrors) near team A until the 20-step pearl rate is below `limit`."""
    dA = m.bfs(m.heads(0))
    rate = lambda: sum(2.0 / (lo + hi) for t, (lo, hi) in m.beds.items() if dA.get(t, INF) <= 20)
    guard = 0
    while rate() >= limit and guard < 5000:
        near = [t for t in m.beds if dA.get(t, INF) <= 20]
        m.del_bed(m.r.choice(near))
        guard += 1


def partition(r, n, total):
    lens = []
    if r.random() < 0.6:
        lens.append(r.randint(12, min(25, total - 2 * (n - 1))))
    rest = n - len(lens)
    rem = total - sum(lens)
    cap = max(9, -(-rem // rest))
    parts = [2] * rest
    extra = rem - 2 * rest
    while extra > 0:
        i = r.randrange(rest)
        if parts[i] < cap:
            parts[i] += 1
            extra -= 1
    return sorted(lens + parts, reverse=True)


MED_GAPS = [(5, 30), (10, 60), (20, 100), (1, 50), (10, 40), (30, 200)]
SMALL_SIZES = [(16, 16), (20, 20), (24, 24), (25, 25), (32, 16), (32, 32), (40, 24), (25, 35), (30, 30), (36, 24),
               (44, 24), (32, 20), (28, 28), (24, 40), (20, 32), (33, 33)]
LARGE_SIZES = [(40, 40), (48, 32), (60, 40), (64, 32), (64, 48), (64, 64), (48, 48), (50, 30), (36, 36), (56, 40),
               (40, 30), (64, 40)]


def sprinkle(m, region, density, gaps, occ):
    rl = sorted(region)
    for _ in range(int(density * len(rl))):
        t = m.r.choice(rl)
        if t in occ or t in m.beds:
            continue
        m.set_bed(t, *m.r.choice(gaps))


# ---------------------------------------------------------------------------------------------------------------
# Families
# ---------------------------------------------------------------------------------------------------------------
def add_box(m, region, taken, fount_gap):
    """A kelp-walled 2x2 / 2x3 / 3x2 box of fountains whose only entrance is a portal: the portal sits on an edge
    inside the box, its partner on an open edge elsewhere in the region (Portals' fountain boxes)."""
    r = m.r
    bw, bh = r.choice([(2, 2), (2, 2), (2, 3), (3, 2)])
    x0, y0 = r.randrange(0, m.w - bw + 1), r.randrange(0, m.h - bh + 1)
    box = {(x0 + i, y0 + j) for i in range(bw) for j in range(bh)}
    margin = {((x + dx) % m.w, (y + dy) % m.h) for x, y in box for dx in (-1, 0, 1) for dy in (-1, 0, 1)}
    if not margin <= region or margin & taken or {m.T(t) for t in margin} & margin:
        return None
    snap = m.snapshot()
    for t in box:
        for d in DIRS:
            e = m.side(t, d)
            if m.adj(t, d) in box:
                m.del_kelp(e)
            else:
                m.add_kelp(e)
    inner = sorted({m.side(t, d) for t in box for d in "ES" if m.adj(t, d) in box})
    ie = r.choice(inner)
    cands = [e for e in ((ie[0], x, y) for x in range(m.w) for y in range(m.h))
             if e not in m.kelp and e not in m.portal
             and all(t in region and t not in margin and t not in taken for t in m.edge_tiles(e))]
    r.shuffle(cands)
    for e in cands[:30]:
        if m.can_portal(ie, e):
            m.add_portal(ie, e)
            if connected(m, region):
                for t in box:
                    m.set_bed(t, *fount_gap())
                return box, margin
            m.del_portal(ie)
    m.restore(snap)
    return None


def gen_sep(r):
    w, h = r.choice([(32, 16), (32, 20), (36, 18), (40, 20), (40, 24), (48, 24), (24, 24), (32, 32), (28, 28),
                     (44, 22), (48, 32), (36, 24)])
    m = M(w, h, r.choice(["y", "xy"]), r)
    half = w // 2
    for y in range(h):
        m.add_kelp(("V", 0, y))
        m.add_kelp(("V", half, y))
    A = {(x, y) for x in range(half) for y in range(h)}
    style = r.choice(["boxes", "boxes", "open", "rooms"])
    rand_walls(m, {"boxes": r.choice([0.04, 0.07, 0.1]), "open": r.choice([0.03, 0.06]),
                   "rooms": r.choice([0.12, 0.16, 0.2])}[style], region=A)
    boxes, taken, placed = set(), set(), 0
    fgap = lambda: (1, 1) if r.random() < 0.7 else (1, r.choice([2, 3, 5]))
    nbox = r.randint(2, max(2, min(8, len(A) // 70))) if style == "boxes" else r.randint(0, 2)
    for _ in range(nbox * 25):
        if placed >= nbox:
            break
        got = add_box(m, A, taken, fgap)
        if got:
            boxes |= got[0]
            taken |= got[1]
            placed += 1
    if not connected(m, A):
        raise Retry("half not connected")
    for _ in range(r.randint(2, 4)):
        place_dragon(m, r.randint(3, 4), region=A, avoid=boxes | taken, sep=0)
    occ = m.occupied()
    open_a = A - boxes
    if style != "boxes" or not boxes:
        for _ in range(r.randint(1, 3)):
            fountain_cluster(m, r.choice(sorted(open_a - occ)), r.randint(2, 5), open_a, fgap(), occ)
    sprinkle(m, open_a, r.choice([0.03, 0.06, 0.1]), MED_GAPS, occ)
    if r.random() < 0.4:
        m = m.transposed()
    return m


def gen_far(r):
    w, h = r.choice([(48, 24), (40, 24), (48, 32), (56, 28), (64, 32), (40, 32), (60, 30), (64, 24), (52, 26),
                     (44, 28), (48, 28), (56, 32)])
    m = M(w, h, r.choice(["y", "xy"]), r)
    c = r.choice([1, 2, 2]) if h % 2 == 0 else 1
    half = w // 2
    R = r.randint(6, 12)
    while (half - R) % c:
        R += 1
    nx, ny = (half - R) // c, h // c
    vw = r.random() < 0.5                           # the maze wraps top-bottom
    for y in range(h):                              # wrap wall, room wall, centre line
        for x in (0, R, half):
            m.add_kelp(("V", x, y))
    for i in range(1, nx):
        for y in range(h):
            m.add_kelp(("V", R + i * c, y))
    for j in range(ny):
        for x in range(R, half):
            m.add_kelp(("H", x, j * c))

    def wall(i, j, di, dj):
        if di == 1:
            return [("V", R + (i + 1) * c, j * c + k) for k in range(c)]
        if di == -1:
            return [("V", R + i * c, j * c + k) for k in range(c)]
        if dj == 1:
            return [("H", R + i * c + k, ((j + 1) * c) % h) for k in range(c)]
        return [("H", R + i * c + k, j * c) for k in range(c)]

    start = (r.randrange(nx), r.randrange(ny))
    seen, stack = {start}, [start]
    while stack:                                    # recursive backtracker: long corridors
        i, j = stack[-1]
        nbrs = []
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if not 0 <= ni < nx:
                continue
            if not 0 <= nj < ny:
                if not vw:
                    continue
                nj %= ny
            if (ni, nj) not in seen:
                nbrs.append((di, dj, ni, nj))
        if not nbrs:
            stack.pop()
            continue
        di, dj, ni, nj = r.choice(nbrs)
        for e in wall(i, j, di, dj):
            m.del_kelp(e)
        seen.add((ni, nj))
        stack.append((ni, nj))
    braid = r.choice([0.0, 0.05, 0.1, 0.2, 0.3])
    for i in range(nx):
        for j in range(ny):
            for di, dj in ((1, 0), (0, 1)):
                if i + di >= nx or (j + dj >= ny and not vw):
                    continue
                es = wall(i, j, di, dj)
                if all(e in m.kelp for e in es) and r.random() < braid:
                    for e in es:
                        m.del_kelp(e)
    for j in r.sample(range(ny), r.randint(1, min(3, ny))):   # openings between the two maze halves
        for k in range(c):
            m.del_kelp(("V", half, j * c + k))
    room = {(x, y) for x in range(R) for y in range(h)}
    maze = {(x, y) for x in range(R, half) for y in range(h)}
    # portal partners in the room-side part of the maze (Trauma: the portals land near the room), so the way to
    # the enemy still runs through the whole maze
    reach = R + max(2, int((half - R) * r.choice([0.3, 0.5, 0.6])))
    walls_in = [e for e in sorted(m.kelp) if e[0] == "V" and R < e[1] <= reach]
    for _ in range(r.randint(1, 3)):                # room <-> maze only through portals on the room wall
        for _ in range(60):
            a, b = ("V", R, r.randrange(h)), r.choice(walls_in)
            if b in m.kelp and m.can_portal(a, b):
                m.add_portal(a, b)
                break
    if not m.portal:
        raise Retry("no room portal")
    for _ in range(r.randint(2, 3)):
        place_dragon(m, r.randint(3, 5), region=room, sep=0)
    if not connected(m, set(m.tiles()), seed=m.heads(0)[0]):
        raise Retry("map not connected")
    occ = m.occupied()
    dA = m.bfs(m.heads(0))
    far_ok = [t for t in sorted(maze) if 10 <= dA.get(t, INF) <= 45] or sorted(maze)
    for _ in range(r.randint(1, 3)):                # fountain clusters inside the maze (behind the portals)
        fountain_cluster(m, r.choice(far_ok), r.randint(2, 6), maze, (1, 1) if r.random() < 0.7 else
                         (1, r.choice([2, 3, 5, 8])), occ)
    sprinkle(m, maze, r.choice([0.02, 0.05, 0.08]), [(5, 30), (10, 60), (20, 100), (10, 200)], occ)
    sprinkle(m, room, r.choice([0.02, 0.04, 0.06]), [(1, 100), (1, 200), (1, 300)], occ)
    if r.random() < 0.3:
        m = m.transposed()
    return m


def gen_rich(r):
    w, h = r.choice([(48, 32), (56, 28), (60, 30), (64, 32), (48, 40), (64, 40), (40, 40), (50, 30), (63, 27),
                     (54, 36), (64, 48), (44, 36)])
    m = M(w, h, r.choice(["xy", "xy", "y", "x"]), r)
    rand_walls(m, r.choice([0.02, 0.05, 0.1, 0.15]))
    rand_portals(m, r.choice([0, 0, 1, 2]))
    for n in partition(r, r.randint(5, 8), r.randint(40, 60)):
        place_dragon(m, n, sep=5)
    occ = m.occupied()
    dA = m.bfs(m.heads(0))
    everywhere = set(m.tiles())
    near = [t for t in sorted(dA) if 3 <= dA[t] <= 20 and t not in occ]
    for _ in range(r.randint(2, 5)):
        fountain_cluster(m, r.choice(near), r.randint(2, 6), everywhere, r.choice([(1, 1), (1, 5), (1, 10)]), occ)
    sprinkle(m, everywhere, r.uniform(0.04, 0.12), [(1, 5), (1, 10), (1, 20), (5, 30), (1, 60), (1, 100)], occ)
    if r.random() < 0.3:                            # Slithery's very slow background beds
        hi = r.choice([500, 1000, 2559])
        for t in everywhere - occ:
            if t not in m.beds:
                m.set_bed(t, 1, hi)
    return m


def spawn_team(m, lengths, near_mirror=None):
    """Dragons for team A; the first head within `near_mirror` of its own mirror image keeps contact short."""
    for i, n in enumerate(lengths):
        ok = (lambda t: 4 <= m.tdist(t, m.T(t)) <= near_mirror) if (near_mirror and i == 0) else None
        place_dragon(m, n, sep=4, head_ok=ok)


def gen_small(r):
    w, h = r.choice(SMALL_SIZES)
    m = M(w, h, r.choice(["x", "y", "xy"]), r)
    rand_walls(m, r.choice([0.0, 0.05, 0.1, 0.15, 0.25]))
    rand_portals(m, r.choice([0, 0, 1, 2, 3]))
    spawn_team(m, [r.randint(2, 5) for _ in range(r.choice([2, 2, 3, 3, 4]))], near_mirror=24)
    occ = m.occupied()
    everywhere = set(m.tiles())
    style = r.choice(["sparse", "medium", "fountains", "uniform"])
    if style == "uniform":
        hi = r.choice([100, 200, 300])
        for t in everywhere - occ:
            m.set_bed(t, 1, hi)
    elif style == "sparse":
        sprinkle(m, everywhere, r.uniform(0.03, 0.08), [(1, 50), (1, 100), (5, 30), (10, 100)], occ)
    elif style == "medium":
        sprinkle(m, everywhere, r.uniform(0.06, 0.15), [(10, 40), (20, 50), (20, 80), (10, 60)], occ)
    else:
        for _ in range(r.randint(1, 3)):
            fountain_cluster(m, r.choice(sorted(everywhere - occ)), r.randint(2, 4), everywhere, (1, 1), occ)
        sprinkle(m, everywhere, r.uniform(0.04, 0.1), [(5, 30), (10, 60), (20, 100)], occ)
    thin_rate(m, 19.0)
    return m


def gen_large(r):
    w, h = r.choice(LARGE_SIZES)
    m = M(w, h, r.choice(["x", "y", "xy"]), r)
    rand_walls(m, r.choice([0.0, 0.02, 0.04, 0.06]))
    rand_portals(m, r.choice([0, 0, 1, 2]))
    spawn_team(m, [r.randint(3, 6) for _ in range(r.choice([2, 3, 3, 4]))], near_mirror=34)
    occ = m.occupied()
    everywhere = set(m.tiles())
    style = r.choice(["sparse", "sparse", "uniform", "fewfount"])
    if style == "uniform":                          # Big Empty: every tile a slow bed
        hi = r.choice([300, 500, 750, 1000])
        for t in everywhere - occ:
            m.set_bed(t, 1, hi)
    else:
        sprinkle(m, everywhere, r.uniform(0.01, 0.04), [(1, 50), (5, 100), (10, 100), (1, 100), (20, 200)], occ)
        if style == "fewfount":
            for _ in range(r.randint(1, 2)):
                fountain_cluster(m, r.choice(sorted(everywhere - occ)), r.randint(2, 3), everywhere, (1, 1), occ)
    thin_rate(m, 19.0)
    return m


def gen_scatter(r):
    w, h = r.choice(SMALL_SIZES + LARGE_SIZES)
    m = M(w, h, r.choice(["x", "y", "xy"]), r)
    rand_walls(m, r.choice([0.0, 0.03, 0.06, 0.1, 0.15]))
    rand_portals(m, r.choice([0, 0, 1, 2]))
    spawn_team(m, [r.randint(3, 4) for _ in range(r.choice([2, 3, 3, 4]))], near_mirror=30)
    occ = m.occupied()
    s = r.randint(3, 6)
    p = r.uniform(0.35, 0.65)
    for gx in range(0, w, s):                       # jittered grid: one bed per s x s cell with probability p
        for gy in range(0, h, s):
            if r.random() >= p:
                continue
            t = ((gx + r.randrange(s)) % w, (gy + r.randrange(s)) % h)
            if t in occ or t in m.beds:
                continue
            lo = r.randint(3, 20)
            m.set_bed(t, lo, lo + r.choice([15, 25, 40, 60, 90]))
    thin_rate(m, 19.0)
    return m


GEN = {"SEP": gen_sep, "FAR_gated": gen_far, "RICH": gen_rich, "SMALL": gen_small, "LARGE": gen_large,
       "SCATTER": gen_scatter}


# ---------------------------------------------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------------------------------------------
def validate(m):
    """Legal and exactly symmetric under the declared SYMMETRY; returns a list of problems."""
    bad = []
    if m.sym not in ("x", "y", "xy"):
        bad.append("symmetry")
    for e in m.kelp | set(m.portal):
        k, x, y = e
        if not (0 <= x < m.w and 0 <= y < m.h):
            bad.append(f"edge off map {e}")
        if m.TE(e) not in (m.kelp if e in m.kelp else m.portal):
            bad.append(f"edge not mirrored {e}")
    if m.kelp & set(m.portal):
        bad.append("kelp and portal on one edge")
    ids = collections.Counter(m.portal.values())
    if any(v != 2 for v in ids.values()):
        bad.append("portal id without exactly two ends")
    for e, f in m.partner.items():
        if e[0] != f[0]:
            bad.append("portal joins H to V")
        if m.partner.get(m.TE(e)) != m.TE(f):
            bad.append(f"portal pair not mirrored {e}")
    for t, (lo, hi) in m.beds.items():
        if not (1 <= lo <= hi):
            bad.append(f"bad gaps {t}")
        if m.beds.get(m.T(t)) != (lo, hi):
            bad.append(f"bed not mirrored {t}")
    seen = set()
    A = [b for tm, b in m.dragons if tm == 0]
    B = [b for tm, b in m.dragons if tm == 1]
    if sorted(map(tuple, ([m.T(t) for t in b] for b in A))) != sorted(map(tuple, B)):
        bad.append("dragons not mirrored")
    for tm, b in m.dragons:
        if len(b) < 2:
            bad.append("dragon too short")
        for i, t in enumerate(b):
            if not (0 <= t[0] < m.w and 0 <= t[1] < m.h):
                bad.append("segment off map")
            if t in seen:
                bad.append(f"overlap {t}")
            seen.add(t)
            if i and abs(t[0] - b[i - 1][0]) + abs(t[1] - b[i - 1][1]) != 1:
                bad.append("segments not adjacent")
            elif i and m.plain(b[i - 1], DELTA_DIR[(t[0] - b[i - 1][0], t[1] - b[i - 1][1])]) != t:
                bad.append("kelp or portal inside a body")
    return bad


def seed_of(base, fam, idx, attempt):
    return int(hashlib.sha256(f"{base}:{fam}:{idx}:{attempt}".encode()).hexdigest()[:12], 16)


def build(job):
    fam, idx, base, out = job
    reasons = collections.Counter()
    for attempt in range(300):
        seed = seed_of(base, fam, idx, attempt)
        try:
            m = GEN[fam](random.Random(seed))
        except Retry as e:
            reasons[str(e)] += 1
            continue
        bad = validate(m)
        if bad:
            reasons["invalid: " + bad[0]] += 1
            continue
        f = feat(m)
        if not INTENT[fam](f):
            reasons[f"class {f['cls2']}"] += 1
            continue
        name = f"{fam}_{idx:02d}"
        path = os.path.join(out, fam, name + ".map")
        with open(path, "w") as fh:
            fh.write(m.text(name))
        return dict(file=os.path.relpath(path, out), family=fam, seed=seed, attempt=attempt,
                    rejected=dict(reasons), **f)
    raise RuntimeError(f"{fam} {idx}: no valid map in 300 attempts {dict(reasons)}")


# ---------------------------------------------------------------------------------------------------------------
# Checks: engine parse (via unswbc's own Python), classifier confusion, optional starter games
# ---------------------------------------------------------------------------------------------------------------
ENGINE_PROBE = r"""
import sys, json
from unswbc.engine import EngineModule
eng = EngineModule()
for p in sys.stdin.read().splitlines():
    notes = []
    try:
        res = eng.run(open(p, 'rb').read(), lambda d, b: b'', on_notice=notes.append, debug=0)
        print(json.dumps({'path': p, 'ok': True, 'notes': notes[:3]}))
    except Exception as e:
        print(json.dumps({'path': p, 'ok': False, 'err': str(e)[:300], 'notes': notes[:3]}))
"""


def unswbc_python():
    exe = shutil.which(unswbc())
    if not exe:
        return None
    with open(os.path.realpath(exe), "rb") as fh:
        first = fh.readline().decode(errors="replace").strip()
    return first[2:].strip() if first.startswith("#!") else None


def engine_parse(paths):
    """Load every map in the real engine (null bots: every dragon suicides in round 0, so this is a parse check)."""
    py = unswbc_python()
    if not py:
        return None
    p = subprocess.run([py, "-c", ENGINE_PROBE], input="\n".join(paths), capture_output=True, text=True, timeout=900)
    return [json.loads(l) for l in p.stdout.splitlines() if l.startswith("{")]


def play(path, bots_dir):
    rel = os.path.relpath(path, bots_dir)
    p = subprocess.run([unswbc(), "run", rel, "starter", "starter", "--no-replay"], capture_output=True, text=True,
                       timeout=1800, cwd=bots_dir)
    return p.returncode, result_line(p.stdout + p.stderr)


def result_line(out):
    lines = [l.strip() for l in out.splitlines() if " wins after " in l or "draw" in l.lower()]
    return lines[-1] if lines else (out.strip().splitlines() or [""])[-1]


def check(root, nplay, bots=None):
    paths = sorted(os.path.join(dp, f) for dp, _, fs in os.walk(root) for f in fs if f.endswith(".map"))
    fam_of = lambda p: os.path.basename(os.path.dirname(p))
    conf = collections.defaultdict(collections.Counter)
    tags = collections.defaultdict(collections.Counter)
    hits = collections.Counter()
    tot = collections.Counter()
    invalid = 0
    for p in paths:
        m = parse(open(p).read())
        bad = validate(m)
        if bad:
            invalid += 1
            print("INVALID", p, bad[:3])
        f = feat(m)
        fam = fam_of(p)
        conf[fam][f["cls2"]] += 1
        tags[fam]["gated"] += f["gated"]
        tags[fam]["eco F"] += f["eco"] == "F"
        tags[fam]["no fountain"] += f["fount"] == 0
        tot[fam] += 1
        if fam in EXPECT:
            hits[fam] += classifier_ok(fam, f)
    print(f"maps {len(paths)}, own-validator failures {invalid}")
    cols = ["SEP", "FAR", "RICH", "SMALL", "LARGE"]
    print("family     | n  | " + " | ".join(f"{c:5}" for c in cols) + " | gated | eco F | no fount | intended")
    for fam in sorted(conf, key=lambda k: CLASSES.index(k) if k in CLASSES else 99):
        print(f"{fam:10} | {tot[fam]:2} | " + " | ".join(f"{conf[fam][c]:5}" for c in cols)
              + f" | {tags[fam]['gated']:5} | {tags[fam]['eco F']:5} | {tags[fam]['no fountain']:8} | "
              + (f"{hits[fam]}/{tot[fam]}" if fam in EXPECT else "-"))
    res = engine_parse(paths)
    if res is None:
        print("engine parse: unswbc not found, skipped")
    else:
        errs = [r for r in res if not r["ok"]]
        notes = [r for r in res if r["notes"]]
        print(f"engine parse: {len(res) - len(errs)}/{len(paths)} ok, {len(notes)} with notices")
        for r in errs[:10]:
            print("  ENGINE", r["path"], r["err"])
    if nplay:
        bdir = bots or bots_dir()
        by = collections.defaultdict(list)
        for p in paths:
            by[fam_of(p)].append(p)
        for fam in sorted(by):
            for p in by[fam][:nplay]:
                code, last = play(p, bdir)
                print(f"play {os.path.relpath(p, root)}: exit {code}: {last}")


# ---------------------------------------------------------------------------------------------------------------
def show(path):
    m = parse(open(path).read())
    body = {}
    for tm, b in m.dragons:
        for i, t in enumerate(b):
            body[t] = ("A" if tm == 0 else "B") if i == 0 else ("a" if tm == 0 else "b")
    for y in range(m.h):
        top, row = "", ""
        for x in range(m.w):
            e = ("H", x, y)
            top += "+" + ("--" if e in m.kelp else "pp" if e in m.portal else "  ")
            v = ("V", x, y)
            row += "|" if v in m.kelp else "P" if v in m.portal else " "
            if (x, y) in body:
                c = body[(x, y)]
            elif (x, y) in m.beds:
                hi = m.beds[(x, y)][1]
                c = "F" if hi <= 10 else "o" if hi <= 60 else "."
            else:
                c = " "
            row += c + " "
        print(top)
        print(row)
    f = feat(m)
    print({k: f[k] for k in ("cls2", "eco", "gated", "area", "contact_bfs", "rate_within20", "start_dragons",
                             "start_len", "fount", "portal_pairs", "kelp_per_tile")})


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--out", default="maps/cls", help="output folder (default maps/cls)")
    ap.add_argument("--classes", default=",".join(CLASSES))
    ap.add_argument("--count", type=int, default=24)
    ap.add_argument("--seed", type=int, default=1)
    ap.add_argument("--jobs", type=int, default=8)
    ap.add_argument("--check", metavar="DIR")
    ap.add_argument("--play", type=int, default=0, help="with --check: starter vs starter games per class")
    ap.add_argument("--show", metavar="MAP")
    ap.add_argument("--bots", help="with --play: the unswbc workspace holding starter/ (default: <repo>/bots)")
    a = ap.parse_args(argv)
    if a.show:
        return show(a.show)
    if a.check:
        return check(a.check, a.play, a.bots)
    fams = [c for c in a.classes.split(",") if c]
    for fam in fams:
        if fam not in GEN:
            sys.exit(f"unknown class {fam}; choose from {CLASSES}")
        os.makedirs(os.path.join(a.out, fam), exist_ok=True)
    jobs = [(fam, i, a.seed, a.out) for fam in fams for i in range(a.count)]
    with cf.ProcessPoolExecutor(a.jobs) as ex:
        rows = list(ex.map(build, jobs))
    man_path = os.path.join(a.out, "manifest.json")
    old = []
    if os.path.exists(man_path):
        with open(man_path) as fh:
            old = [r for r in json.load(fh).get("maps", []) if r["family"] not in fams]
    # fixed order (class, file), so a partial rerun merged into the manifest matches a full run byte for byte
    rows = sorted(old + rows, key=lambda r: (CLASSES.index(r["family"]) if r["family"] in CLASSES else 99, r["file"]))
    with open(man_path, "w") as fh:
        json.dump(dict(generator="abyss_tools.maps.mapgen_cls", seed=a.seed, maps=rows), fh, indent=1)
    for fam in fams:
        rs = [r for r in rows if r["family"] == fam]
        first = sum(r["attempt"] == 0 for r in rs)
        print(f"{fam:10} {len(rs)} maps, first-try {first}/{len(rs)}, attempts mean "
              f"{sum(r['attempt'] + 1 for r in rs) / len(rs):.1f}")


if __name__ == "__main__":
    main()
